-- Create "action_log" table
CREATE TABLE "action_log" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "type" character varying NOT NULL, "action_group" character varying NOT NULL, "actor_id" bigint NULL, "actor_name" character varying NOT NULL DEFAULT '', "ip" character varying NOT NULL DEFAULT '', "object_kind" character varying NOT NULL DEFAULT '', "object_id" character varying NOT NULL DEFAULT '', "object_label" character varying NOT NULL DEFAULT '', "object_type" character varying NOT NULL DEFAULT '', "object_url" character varying NOT NULL DEFAULT '', "changes" text NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- Create index "action_log_created_at" to table: "action_log"
CREATE INDEX "action_log_created_at" ON "action_log" ("created_at");
-- Create index "action_log_group_created_at" to table: "action_log"
CREATE INDEX "action_log_group_created_at" ON "action_log" ("action_group", "created_at");
-- Create index "action_log_actor_created_at" to table: "action_log"
CREATE INDEX "action_log_actor_created_at" ON "action_log" ("actor_id", "created_at");
-- Create index "action_log_object" to table: "action_log"
CREATE INDEX "action_log_object" ON "action_log" ("object_kind", "object_id");
-- Create "action_log_settings" table
CREATE TABLE "action_log_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "keep_days" bigint NOT NULL DEFAULT 90, "log_ip" boolean NOT NULL DEFAULT true, "groups_off" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
